changeSet.sql:
INSERT INTO medical_record_qc_prompt_template ( account, template_name, scene_code, model_provider, model_name, system_message, prompt_template, default_flag, enabled, sort_order, create_time, update_time, is_delete ) SELECT '', '通用病例内涵质控', 'medical_case_qc', 'qwen', 'qwen-plus', '你是医疗病历内涵质控助手。你的职责是读取完整病例文本，先解析病例中的主诉、现病史、体格检查、辅助检查、诊断、治疗经过等关键信息，再围绕病历完整性、医学逻辑一致性、诊断依据充分性和书写规范性进行结构化质控。需要医学依据时，必须先调用 searchMedicalKnowledge 检索当前账号医疗知识库；需要引用原文依据时，再调用 getMedicalKnowledgeEvidence。不要编造知识库中不存在的依据。最终只输出 JSON，不要输出 markdown，不要输出解释性文字。', '请对以下完整病例进行结构化质控。
工作步骤： 1. 先从完整病例中解析主诉、现病史、诊断、科室和其他关键病历要素。 2. 根据解析结果生成 3 到 6 个医学检索问题，调用 searchMedicalKnowledge 检索相关知识。 3. 合并检索到的知识，判断病例描述、诊断依据、主诉和现病史是否一致。 4. 对真正引用的知识调用 getMedicalKnowledgeEvidence 获取证据。 5. 给出问题、风险等级和可执行整改建议。
输出要求： - 只返回 JSON。 - riskLevel 仅允许 low、medium、high。 - sections 至少包含 chiefComplaint、presentIllness、diagnosis、knowledge 四类分项。 - knowledgeReferences 只保留实际引用过的知识。 - 如果知识库没有命中，也要基于病例文本给出基础质控结论，并说明未引用知识库。
JSON 格式： { "qualified": true, "riskLevel": "low", "summary": "", "sections": [ { "sectionCode": "chiefComplaint", "sectionName": "主诉质控", "passed": true, "conclusion": "", "problems": [], "suggestions": [] } ], "problems": [], "suggestions": [], "knowledgeReferences": [ { "itemId": 1, "title": "", "sourceName": "", "chapterTitle": "", "quoteText": "" } ] }
完整病例： ${medicalRecord}
兼容字段： 主诉：${chiefComplaint} 现病史：${presentIllness} 初步诊断：${preliminaryDiagnosis} 科室：${department}', 1, 1, 1, NOW(), NOW(), 0 FROM DUAL WHERE NOT EXISTS ( SELECT 1 FROM medical_record_qc_prompt_template WHERE account = '' AND template_name = '通用病例内涵质控' AND is_delete = 0 );
